patch.unified_diff:
===================================================================
--- a/src/tools.ts
+++ b/src/tools.ts
@@ -1,29 +1,29 @@
 import { z } from "zod";

 export const listIssuesTool = {
   name: "list_issues",
-  description: "List issues.",
+  description: "List issues, optionally filtered by status or assignee and capped with limit. Use to browse or filter issues by those fields; use search_issues when you have a text query, and get_issue when you already have an issue ID. Comments are included only when include_comments is true.",
   params: {
-    status: z.string().optional(),
-    assignee: z.string().optional(),
-    include_comments: z.boolean().optional(),
-    limit: z.number().optional(),
+    status: z.string().optional().describe("Filter issues by status."),
+    assignee: z.string().optional().describe("Filter issues by assignee."),
+    include_comments: z.boolean().optional().describe("Set true to include comments with the returned issues, which increases response size."),
+    limit: z.number().optional().describe("Maximum number of issues to return; use a smaller value to keep the response small."),
   },
 };

 export const searchIssuesTool = {
   name: "search_issues",
-  description: "Search issues.",
+  description: "Search issues using a text query. Use when you have keywords or a query to find issues; use list_issues to filter by status or assignee, and get_issue when you already have an issue ID. Comments are included only when include_comments is true.",
   params: {
-    query: z.string(),
-    include_comments: z.boolean().optional(),
+    query: z.string().describe("Text query used to search for issues."),
+    include_comments: z.boolean().optional().describe("Set true to include comments with the matching issues, which increases response size."),
   },
 };

 export const getIssueTool = {
   name: "get_issue",
-  description: "Get a single issue by its ID, for example TRK-117. Returns the title, status, assignee, body and full comment thread.",
+  description: "Get a single issue by its ID, for example TRK-117. Use when you already know the issue ID; use list_issues or search_issues to find issues otherwise. Returns the title, status, assignee, body and full comment thread.",
   params: {
-    id: z.string(),
+    id: z.string().describe("ID of the issue to retrieve, such as TRK-117."),
   },
 };
